cat > /app/output/styles.css <<'EOF'
:root {
  --black: #050505;
  --ink: #18141f;
  --muted: #62596e;
  --line: rgba(17, 17, 17, 0.1);
  --purple: #7638fa;
  --orange: #ff7a00;
  --pink: #ff2fb3;
  --cream: #fff8ef;
  --soft-purple: #f2ebff;
  --soft-blue: #edf7ff;
  --white: #ffffff;
  --shadow: 0 24px 80px rgba(31, 18, 64, 0.14);
  --radius-xl: 36px;
  --radius-lg: 26px;
  --radius-md: 18px;
  --container: min(1160px, calc(100% - 40px));
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  font-family: "Inter", system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: #fffdfb;
  color: var(--ink);
  overflow-x: hidden;
}

body.menu-open {
  overflow: hidden;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
select {
  font: inherit;
}

.container {
  width: var(--container);
  margin: 0 auto;
}

.section-pad {
  padding: 88px 0;
}

.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  padding: 14px 0;
  background: rgba(255, 253, 251, 0.82);
  border-bottom: 1px solid rgba(17, 17, 17, 0.06);
  backdrop-filter: blur(18px);
}

.nav-shell {
  width: var(--container);
  min-height: 58px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 20px;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-weight: 900;
  letter-spacing: -0.04em;
  font-size: 1.25rem;
}

.brand-mark {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border-radius: 13px;
  color: white;
  font-size: 0.84rem;
  letter-spacing: -0.08em;
  background: linear-gradient(135deg, var(--purple), var(--pink) 52%, var(--orange));
  box-shadow: 0 10px 24px rgba(118, 56, 250, 0.28);
}

.nav-menu {
  justify-self: center;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px;
  background: rgba(255, 255, 255, 0.76);
  border: 1px solid var(--line);
  border-radius: 999px;
}

.nav-menu a {
  padding: 10px 15px;
  border-radius: 999px;
  color: #2b2534;
  font-size: 0.94rem;
  font-weight: 700;
  transition: background 180ms ease, color 180ms ease;
}

.nav-menu a:hover,
.nav-menu a:focus-visible {
  color: var(--black);
  background: var(--soft-purple);
}

.login-button,
.primary-cta,
.store-buttons a {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 48px;
  padding: 0 22px;
  border-radius: 999px;
  color: white;
  background: var(--black);
  font-weight: 800;
  box-shadow: 0 16px 32px rgba(0, 0, 0, 0.16);
  transition: transform 180ms ease, box-shadow 180ms ease;
}

.login-button:hover,
.primary-cta:hover,
.store-buttons a:hover {
  transform: translateY(-2px);
  box-shadow: 0 20px 38px rgba(0, 0, 0, 0.2);
}

.menu-toggle {
  display: none;
  width: 46px;
  height: 46px;
  border: 0;
  border-radius: 16px;
  background: var(--black);
  cursor: pointer;
  place-items: center;
  padding: 11px;
}

.menu-toggle span {
  display: block;
  width: 22px;
  height: 2px;
  margin: 3px 0;
  border-radius: 99px;
  background: white;
  transition: transform 180ms ease, opacity 180ms ease;
}

.menu-toggle.is-active span:nth-child(1) {
  transform: translateY(8px) rotate(45deg);
}

.menu-toggle.is-active span:nth-child(2) {
  opacity: 0;
}

.menu-toggle.is-active span:nth-child(3) {
  transform: translateY(-8px) rotate(-45deg);
}

.hero {
  position: relative;
  min-height: 760px;
  display: flex;
  align-items: center;
  overflow: hidden;
  background:
    radial-gradient(circle at 8% 14%, rgba(255, 122, 0, 0.2), transparent 30%),
    radial-gradient(circle at 86% 12%, rgba(118, 56, 250, 0.24), transparent 34%),
    linear-gradient(180deg, #fff8f2 0%, #fffdfb 88%);
}

.hero::before {
  content: "";
  position: absolute;
  inset: 88px 26px 26px;
  border-radius: 52px;
  background: linear-gradient(135deg, rgba(118, 56, 250, 0.12), rgba(255, 47, 179, 0.08), rgba(255, 122, 0, 0.14));
  border: 1px solid rgba(255, 255, 255, 0.7);
}

.hero-bg-orb {
  position: absolute;
  border-radius: 50%;
  filter: blur(10px);
  opacity: 0.75;
}

.hero-bg-orb-one {
  width: 210px;
  height: 210px;
  left: -48px;
  bottom: 120px;
  background: var(--orange);
}

.hero-bg-orb-two {
  width: 260px;
  height: 260px;
  right: -70px;
  top: 140px;
  background: var(--purple);
}

.hero-grid {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: minmax(0, 1.02fr) minmax(380px, 0.78fr);
  gap: 70px;
  align-items: center;
}

.eyebrow {
  margin: 0 0 18px;
  color: var(--purple);
  font-size: 0.78rem;
  font-weight: 900;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

h1,
h2,
h3,
p {
  margin-top: 0;
}

h1 {
  max-width: 800px;
  margin-bottom: 24px;
  font-size: clamp(3.5rem, 9vw, 7.9rem);
  line-height: 0.86;
  letter-spacing: -0.09em;
}

h2 {
  margin-bottom: 22px;
  font-size: clamp(2.35rem, 5vw, 5rem);
  line-height: 0.94;
  letter-spacing: -0.075em;
}

.hero-text,
.section-copy p,
.safety-card p,
.creator-copy p,
.download-card p,
.footer-brand-block p {
  color: var(--muted);
  font-size: 1.08rem;
  line-height: 1.7;
}

.hero-text {
  max-width: 620px;
  margin-bottom: 32px;
  font-size: 1.24rem;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 18px;
}

.primary-cta {
  min-height: 58px;
  padding: 0 30px;
  background: linear-gradient(135deg, var(--purple), var(--pink) 58%, var(--orange));
}

.secondary-link,
.text-link,
.view-more {
  display: inline-flex;
  align-items: center;
  font-weight: 900;
  color: var(--black);
  border-bottom: 2px solid currentColor;
}

.hero-visual {
  position: relative;
  min-height: 580px;
}

.phone-card {
  width: min(365px, 100%);
  min-height: 535px;
  margin-left: auto;
  padding: 24px;
  border-radius: 44px;
  background: rgba(255, 255, 255, 0.72);
  border: 1px solid rgba(255, 255, 255, 0.82);
  box-shadow: var(--shadow);
  backdrop-filter: blur(18px);
  transform: rotate(4deg);
}

.story-row {
  display: flex;
  gap: 10px;
  margin-bottom: 18px;
}

.story-row span {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--orange), var(--pink), var(--purple));
  border: 4px solid white;
}

.post-image {
  height: 315px;
