  background: #ebe4f5;
}

.post-lines span:nth-child(1) { width: 88%; }
.post-lines span:nth-child(2) { width: 64%; }
.post-lines span:nth-child(3) { width: 42%; }

.floating-card,
.floating-bubble {
  position: absolute;
  display: inline-flex;
  align-items: center;
  gap: 10px;
  border-radius: 999px;
  background: white;
